import { apiFailureMessage, parseBody } from "../../../shared/apiError";
import type {
  ApiError,
  CashierAccountDto,
  CashierCheckoutResultDto,
  CashierDashboardDto,
  StaffServiceRequestDto,
  CashierHistoryDto,
  CashierReportScreenDto,
  CashierReservationCheckInResultDto,
  ReservationDto,
  StaffSessionDto,
} from "./types";

const jsonHeaders = { "Content-Type": "application/json" };

/** VietQR generated by the server; the image is a PNG in base64. */
export type TransferQrDto = {
  bankName: string;
  accountNumber: string;
  accountName: string;
  amount: number;
  content: string;
  payload: string;
  qrPngBase64: string;
  /** The system confirms this transfer by itself when the money arrives (SePay on, app payment). */
  autoConfirm?: boolean;
};

export type OnsitePayment = {
  paymentId: number; paymentCode: string; amount: number; currency: string;
  method: string; location: string; status: string; diningSessionId: number;
  diningSessionCode: string; tableId: number; splitPart: string | null; isCurrentAttempt: boolean;
  /** "SEPAY" when the bank transfer was confirmed automatically. */
  providerName?: string | null;
};

/** A received transfer (SePay) that was not confirmed automatically and needs the cashier. */
export type BankTransferAlert = {
  eventId: number; amount: number; content: string; outcome: string; paymentId: number | null;
  referenceCode: string | null; receivedAtUtc: string; transactionDate: string | null;
  expectedAmount: number | null; tableId: number | null;
};

async function request<T>(input: string, init?: RequestInit): Promise<T> {
  const response = await fetch(input, {
    credentials: "include",
    headers: init?.body ? { ...jsonHeaders, ...(init.headers ?? {}) } : init?.headers,
    ...init,
  });

  const text = await response.text();
  const payload = parseBody(text);
  if (!response.ok) {
    throw new Error(apiFailureMessage(response.status, payload));
  }
  return payload as T;
}

export const cashierApi = {
  getOrderTransferQr: (orderId: number, amount: number, signal?: AbortSignal) =>
    request<TransferQrDto>(`/api/gateway/staff/cashier/transfer-qr?orderId=${orderId}&amount=${Math.round(amount)}`, { signal }),
  getPaymentTransferQr: (paymentId: number) =>
    request<TransferQrDto>(`/api/gateway/staff/cashier/onsite-payments/${paymentId}/transfer-qr`),
  getOnsitePayments: (signal?: AbortSignal) => request<OnsitePayment[]>("/api/gateway/staff/cashier/onsite-payments", { signal }),
  confirmOnsitePayment: (id: number) => request<{ paymentId: number; status: string }>(
    `/api/gateway/staff/cashier/onsite-payments/${id}/confirm`, { method: "POST", body: "{}" }),
  cancelOnsitePayment: (id: number) => request<{ paymentId: number; status: string }>(
    `/api/gateway/staff/cashier/onsite-payments/${id}/cancel`, { method: "POST", body: "{}" }),
  getBankTransferAlerts: (signal?: AbortSignal) =>
    request<BankTransferAlert[]>("/api/gateway/staff/cashier/bank-transfers/alerts", { signal }),
  resolveBankTransferAlert: (eventId: number) =>
    request<{ success: boolean; message: string }>(`/api/gateway/staff/cashier/bank-transfers/${eventId}/resolve`, { method: "POST", body: "{}" }),
  getSession: () => request<StaffSessionDto>("/api/gateway/staff/cashier/session"),
  login: (username: string, password: string) =>
    request<{ success: boolean; nextPath?: string; session: StaffSessionDto }>("/api/gateway/staff/auth/login", {
      method: "POST",
      body: JSON.stringify({ username, password }),
    }),
  logout: () => request<{ success: boolean; nextPath?: string }>("/api/gateway/staff/cashier/auth/logout", { method: "POST", body: JSON.stringify({}) }),
  getDashboard: (signal?: AbortSignal) => request<CashierDashboardDto>("/api/gateway/staff/cashier/dashboard", { signal }),
  getServiceRequests: (signal?: AbortSignal) => request<StaffServiceRequestDto[]>("/api/gateway/staff/cashier/service-requests", { signal }),
  acknowledgeServiceRequest: (id: number) => request<StaffServiceRequestDto>(`/api/gateway/staff/cashier/service-requests/${id}/acknowledge`, { method: "POST", body: "{}" }),
  completeServiceRequest: (id: number) => request<StaffServiceRequestDto>(`/api/gateway/staff/cashier/service-requests/${id}/complete`, { method: "POST", body: "{}" }),
  getHistory: () => request<CashierHistoryDto>("/api/gateway/staff/cashier/history"),
  getReport: (date?: string) => request<CashierReportScreenDto>(`/api/gateway/staff/cashier/report${date ? `?date=${date}` : ""}`),
  /** date: yyyy-MM-dd in restaurant time; omitted = today. */
  getTodayReservations: (branchId?: number | null, status?: string, date?: string) => {
    const params = new URLSearchParams();
    if (branchId && branchId > 0) params.set("branchId", String(branchId));
    if (status && status !== "ALL") params.set("status", status);
    if (date) params.set("date", date);
    const suffix = params.size > 0 ? `?${params.toString()}` : "";
    return request<ReservationDto[]>(`/api/cashier/reservations/today${suffix}`);
  },
  getPendingReservations: (signal?: AbortSignal) => request<ReservationDto[]>("/api/cashier/reservations/pending", { signal }),
  confirmReservation: (reservationId: number) =>
    request<ReservationDto>(`/api/cashier/reservations/${reservationId}/confirm`, { method: "POST", body: "{}" }),
  rejectReservation: (reservationId: number, reason: string) =>
    request<ReservationDto>(`/api/cashier/reservations/${reservationId}/reject`, { method: "POST", body: JSON.stringify({ reason }) }),
  markReservationNoShow: (reservationId: number) =>
    request<ReservationDto>(`/api/cashier/reservations/${reservationId}/no-show`, { method: "POST", body: "{}" }),
  checkInReservation: (reservationId: number, payload: { tableId?: number | null; tableIds?: number[] }) =>
    request<CashierReservationCheckInResultDto>(`/api/cashier/reservations/${reservationId}/check-in`, { method: "POST", body: JSON.stringify({ tableId: payload.tableId ?? null, tableIds: payload.tableIds ?? [] }) }),
  closeDiningSession: (sessionId: number) =>
    request<{ success: boolean; message: string }>(`/api/gateway/staff/cashier/dining-sessions/${sessionId}/close`, { method: "POST", body: "{}" }),
  checkout: (orderId: number, payload: { discount?: number; pointsUsed?: number; paymentMethod?: string; paymentAmount?: number; idempotencyKey: string }) =>
    request<CashierCheckoutResultDto>(`/api/gateway/staff/cashier/orders/${orderId}/checkout`, {
      method: "POST",
      body: JSON.stringify(payload),
    }),
  updateAccount: (payload: { name: string; phone: string; email?: string }) =>
    request<CashierAccountDto>("/api/gateway/staff/cashier/account", { method: "PUT", body: JSON.stringify(payload) }),
  changePassword: (payload: { currentPassword: string; newPassword: string; confirmPassword: string }) =>
    request<{ success: boolean; message: string }>("/api/gateway/staff/cashier/change-password", { method: "POST", body: JSON.stringify(payload) }),
};
